//go:build linux
package main
import("bytes";"fmt";"os";"os/exec";"path/filepath";"strings";"testing";"time")
func TestLockContentionIsNonMutating(t *testing.T){p:=filepath.Join(t.TempDir(),"maintenance");release,e:=lock(p);if e!=nil{t.Fatal(e)};defer release();if other,e:=lock(p);e!=errBusy{if other!=nil{other()};t.Fatal("lock did not refuse contention",e)}}
func TestInheritedControllerLock(t *testing.T){if os.Getenv("NATIVE_TEST_INHERITED")=="1"{if inheritedLock(os.Getenv("NATIVE_TEST_LOCK"))!=nil{os.Exit(17)};os.Exit(0)};p:=filepath.Join(t.TempDir(),"maintenance");exe,e:=os.Executable();if e!=nil{t.Fatal(e)};cmd:=exec.Command("sh","-c",`exec 9>"$1"; flock -n 9; exec "$2" -test.run '^TestInheritedControllerLock$'`,"sh",p,exe);cmd.Env=append(os.Environ(),"NATIVE_TEST_INHERITED=1","NATIVE_TEST_LOCK="+p);if out,e:=cmd.CombinedOutput();e!=nil{t.Fatalf("inherited lock rejected: %v %s",e,out)};if e=inheritedLock(p);e==nil{t.Fatal("unrelated/missing inherited FD accepted")}}
func TestPreparationLeavesExistingInterfacesAlone(t *testing.T){a:=newApp(t.TempDir());mkdir(a.p("/etc/config"));mkdir(a.p("/lib/netifd/proto"));mkdir(a.p("/var/run"));os.WriteFile(a.p("/lib/netifd/proto/amneziawg.sh"),[]byte("fixture"),0600);network:=a.p("/etc/config/network");original:=[]byte("synthetic existing network\n");os.WriteFile(network,original,0600);mutations:=0;a.run=func(_ time.Duration,input []byte,name string,args ...string)([]byte,error){if name!="uci"{t.Fatal("unexpected command",name,args)};joined:=strings.Join(args," ");switch{case joined=="changes network":return nil,nil;case len(args)==3&&args[0]=="-q"&&args[1]=="get":k:=args[2];switch{case strings.HasSuffix(k,".proto"):return []byte("amneziawg"),nil;case strings.HasSuffix(k,".addresses"):if strings.Contains(k,"awg_main"){return []byte("10.8.1.2/32"),nil};return []byte("10.8.1.14/32"),nil;case strings.HasSuffix(k,".home_net_prepared"):return nil,errStopped;case k=="network.awg_main"||k=="network.awg_backup":return []byte("interface"),nil};default:mutations++};return nil,errStopped};status,e:=a.prepareSlots("apartment-main",false);if e!=nil||status["phase"]!="ready"||status["changed"]!=false||mutations!=0{t.Fatal(status,e,mutations)};current,_:=read(network);if !bytes.Equal(current,original){t.Fatal("existing network rewritten")};release,e:=lock(a.p("/var/run/home-net-vpn-maintenance.lock"));if e!=nil{t.Fatal(e)};defer release();status,e=a.prepareSlots("apartment-main",false);if e!=nil||status["phase"]!="blocked"||mutations!=0{t.Fatal(status,e)}}
func TestPreparationNoRoleHasNoCommands(t *testing.T){a:=newApp(t.TempDir());a.run=func(time.Duration,[]byte,string,...string)([]byte,error){t.Fatal("unassigned device attempted command");return nil,errStopped};s,e:=a.prepareSlots("",true);if e!=nil||s["phase"]!="awaiting_role"||s["changed"]!=false{t.Fatal(s,e)}}
func TestNativeDecryptTemporaryPathBounds(t *testing.T){a:=newApp(t.TempDir());mkdir(a.p("/tmp"));if e:=a.dispatch([]string{"decrypt",a.p("/tmp-evil/in"),a.p("/tmp/out")});e==nil{t.Fatal("path prefix confusion")};if e:=a.dispatch([]string{"decrypt",a.p("/tmp/in"),a.p("/etc/out")});e==nil{t.Fatal("decrypted outside temporary directory")}}
func TestPersistIsAtomicAndRecoverable(t *testing.T){a:=newApp(t.TempDir());network:=a.p("/etc/config/network");mkdir(filepath.Dir(network));mkdir(a.p(vpnRoot+"/transaction/backup"));original:=[]byte("baseline network");os.WriteFile(network,original,0600);conf:=syntheticConf();a.run=func(_ time.Duration,input []byte,name string,args ...string)([]byte,error){if name=="awg"&&sameOrdered(args,[]string{"showconf","awg_backup"}){return conf,nil};if name!="uci"{return nil,errStopped};switch strings.Join(args," "){case "changes network":return nil,nil;case "-q get network.awg_backup.proto":return []byte("amneziawg"),nil;case "-q show network":return []byte("network.awg_backup=interface\n"),nil};if len(args)==5&&args[0]=="-c"&&args[4]=="batch"{if !strings.Contains(string(input),".awg_jc='4'"){t.Fatal("obfuscation not persisted")};for _,arg:=range args{if strings.Contains(arg,"AQEB"){t.Fatal("private material leaked in arguments")}};return nil,os.WriteFile(filepath.Join(args[1],"network"),[]byte("persisted network"),0600)};return nil,fmt.Errorf("unexpected fixture command")};if e:=a.persist("awg_backup",hash(conf));e!=nil{t.Fatal(e)};current,_:=read(network);if string(current)!="persisted network"{t.Fatal("candidate not committed")};baseline,_:=read(a.p(vpnRoot+"/transaction/backup/network.before-persist"));if !bytes.Equal(baseline,original){t.Fatal("rollback baseline lost")};if e:=a.persist("awg_backup",hash(conf));e!=nil{t.Fatal("retry not idempotent",e)};if e:=a.restorePersisted();e!=nil{t.Fatal(e)};current,_=read(network);if !bytes.Equal(current,original){t.Fatal("rollback failed")}}
